namespace PhoneRepair.EditorTools
{
    /// <summary>
    /// Where the Phone Fixer art pass lives. The models come from ArtSource/Blender/Scripts/build_pf_*.py
    /// and build_phone_mochi_dango.py; everything else is generated by <see cref="PhoneFixerSetup"/>.
    /// </summary>
    internal static class PhoneFixerPaths
    {
        public const string ModelsRoot = "Assets/_Project/Art/Models";
        public const string ShopFbx = ModelsRoot + "/Environment/PF/ENV_PF_Shop.fbx";
        public const string BenchFbx = ModelsRoot + "/Environment/PF/ENV_PF_RepairBench.fbx";
        public const string PhoneFbx = ModelsRoot + "/Phones/MochiDango/PHN_MochiDango.fbx";
        public const string ToolModelsFolder = ModelsRoot + "/Tools/PF";
        public const string CharacterModelsFolder = ModelsRoot + "/Characters/PF";
        public const string BaseCharacterFbx = CharacterModelsFolder + "/CHR_PF_Base.fbx";

        public const string MaterialsFolder = "Assets/_Project/Art/Materials/PhoneFixer";
        public const string PaletteJson = MaterialsFolder + "/pf_palette.json";
        public const string UiFolder = "Assets/_Project/Art/UI/PhoneFixer";
        public const string PortraitsFolder = "Assets/_Project/Art/UI/Portraits";

        public const string PrefabsFolder = "Assets/_Project/Prefabs/PhoneFixer";
        public const string CharacterPrefabsFolder = PrefabsFolder + "/Characters";
        public const string DataFolder = "Assets/_Project/Data/PhoneFixer";
        public const string ToolDataFolder = DataFolder + "/Tools";
        public const string CharacterDataFolder = DataFolder + "/Characters";
        public const string CustomerControllerPath = CharacterDataFolder + "/AC_PF_Customer.controller";

        public const string ScenesFolder = "Assets/_Project/Scenes/PhoneFixer";
        public const string MenuSceneName = "PF_MainMenu";
        public const string ShopSceneName = "PF_Shop";
        public const string BenchSceneName = "PF_RepairBench";
        public const string MenuScene = ScenesFolder + "/" + MenuSceneName + ".unity";
        public const string ShopScene = ScenesFolder + "/" + ShopSceneName + ".unity";
        public const string BenchScene = ScenesFolder + "/" + BenchSceneName + ".unity";

        public const string RenderingFolder = "Assets/_Project/Settings/Rendering";
        public const string ShopPipelinePath = RenderingFolder + "/PF_URP_Shop.asset";
        public const string ShopRendererPath = RenderingFolder + "/PF_URP_Shop_Renderer.asset";
        public const string ShopVolumePath = RenderingFolder + "/PF_Volume_Shop.asset";
        public const string BenchVolumePath = RenderingFolder + "/PF_Volume_Bench.asset";

        public static readonly string[] CustomerNames = { "Fumi", "Ren", "Sasaki", "Mio", "Kanemochi" };
        public static readonly string[] AnimationClips = { "Idle", "Walk", "Talk", "Celebrate", "Disappointed", "Confused", "Impatient" };
        public static readonly string[] LoopingClips = { "Idle", "Walk", "Talk", "Impatient" };
        public static readonly string[] PropTools = { "Tweezers", "Brush", "Tester" };

        public static string CharacterFbx(string name) => $"{CharacterModelsFolder}/CHR_PF_{name}.fbx";
        public static string CharacterPrefab(string name) => $"{CharacterPrefabsFolder}/CHR_PF_{name}.prefab";
        public static string ToolFbx(string name) => $"{ToolModelsFolder}/TOOL_PF_{name}.fbx";
        public static string Portrait(string name) => $"{PortraitsFolder}/PF_Portrait_{name}.png";

        /// <summary>Prefab root scale per customer. Must match HEIGHT_SCALE in build_pf_customers.py.</summary>
        public static float HeightScale(string name) => name switch
        {
            "Fumi" => 0.94f,
            "Sasaki" => 1.04f,
            "Mio" => 0.9f,
            _ => 1f,
        };
    }
}
